<template><section class="border-t pt-5 mt-6 space-y-4"><h2 class="font-bold">霍尔系数与载流子浓度 · SI 单位</h2><label class="block">评定标题<input v-model="title" class="input"/></label><div class="grid grid-cols-3 gap-2"><b>测量量</b><b>测量值</b><b>标准不确定度</b><template v-for="(label,key) in labels"><label>{{label}}</label><input v-model.number="inputs[key]" type="number" :aria-label="label" class="input"/><input v-model.number="inputs['u'+key]" type="number" min="0" :aria-label="label+'标准不确定度'" class="input"/></template></div><label class="block">包含因子<input v-model.number="inputs.k" type="number" min="0.1" class="input"/></label><label class="flex gap-2"><input v-model="independent" type="checkbox"/>输入量可视为独立</label><p v-if="result.error" class="text-rose-600">{{result.error}}</p><div v-else class="space-y-2"><p>R_H = {{fmt(result.R)}} ± {{fmt(result.UR)}} m³/C</p><p>n = {{fmt(result.n)}} ± {{fmt(result.Un)}} m⁻³</p></div><button class="btn-primary" :disabled="!!result.error||!independent" @click="save">保存传播评定</button></section></template>
<script setup>
import {ref,computed} from 'vue';import calculations from '../../shared/calculations.cjs';import {api} from '../api';const emit=defineEmits(['saved']);const title=ref('霍尔系数与载流子浓度'),independent=ref(false),inputs=ref({mode:'hall',V:null,d:null,I:null,B:null,uV:null,ud:null,uI:null,uB:null,k:2}),labels={V:'霍尔电压 / V',d:'厚度 / m',I:'电流 / A',B:'磁场 / T'};
const result=computed(()=>{try{return calculations.uncertainty({...inputs.value,independent:independent.value})}catch(e){return{error:e.message}}});const fmt=v=>Number.isFinite(v)?v.toExponential(3):'—';async function save(){await api('/workshop/uncertainty',{method:'POST',body:{title:title.value,inputs:{...inputs.value,independent:independent.value}}});emit('saved');}
defineExpose({restore(record){title.value=record.title;inputs.value={...record.inputs};independent.value=record.inputs.independent===true;}});
</script>
